// ELEMENTS:
// 1. Foto (src) desfocada sob navy
// 2. Label, número grande em serifa a contar (anim.text, ex. "2.430 m²"), filete azul IAD e sub
// 3. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { MediaImg as Img } from "../media";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const NAVY_RGB = "0,31,68";
const CYAN = "#DE212B";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.24) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

// "2.430 m²" → counts 0 → 2430 and keeps the pt-PT format (dot thousands, comma decimals).
const countUp = (text: string, t: number): string => {
  const m = text.match(/\d[\d.\s]*(,\d+)?/);
  if (!m) return text;
  const raw = m[0].trim();
  const decimals = m[1] ? m[1].length - 1 : 0;
  const value = parseFloat(raw.replace(/[.\s]/g, "").replace(",", "."));
  if (!isFinite(value)) return text;
  const [int, dec] = (value * t).toFixed(decimals).split(".");
  const grouped = int.length > 3 ? int.replace(/\B(?=(\d{3})+(?!\d))/g, ".") : int;
  return text.slice(0, m.index) + grouped + (dec ? "," + dec : "") + text.slice((m.index ?? 0) + raw.length);
};

const NumeroDestaque: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const label = String(p.label ?? "").trim();
  const sub = String(p.sub ?? "").trim();
  const value = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 22 * u}px)` };
  };
  const count = interpolate(f, [Math.round(0.3 * fps), Math.round(1.6 * fps)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const zoom = interpolate(f, [0, T], [1.04, 1.12], { ...clamp, easing: Easing.inOut(Easing.sin) });
  const rule = show(0.5, 0.9);
  const size = (value.length > 9 ? 150 : 190) * u;

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 24px rgba(0,0,0,0.5)", overflow: "hidden", backgroundColor: NAVY }}>
      <AbsoluteFill style={{ transform: `scale(${zoom})` }}>
        {src ? <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.8) blur(6px)" }} /> : null}
      </AbsoluteFill>
      <AbsoluteFill style={{ background: `rgba(${NAVY_RGB},0.78)` }} />
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", textAlign: "center", padding: `0 ${80 * u}px`, gap: 30 * u }}>
        {label ? (
          <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 38 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(0.1) }}>{label}</div>
        ) : null}
        <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums tabular-nums", fontWeight: 300, fontSize: size, lineHeight: 1, color: WHITE, whiteSpace: "nowrap", ...rise(0.25) }}>
          {countUp(value, count)}
        </div>
        <div style={{ width: rule * 160 * u, height: 3 * u, background: CYAN }} />
        {sub ? (
          <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 64 * u, lineHeight: 1.1, color: WHITE, ...rise(0.9) }}>{sub}</div>
        ) : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: "#DE212B" }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default NumeroDestaque;
